import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,Entrar} from './kit';
// DINERO 28-nov 15:00 (Doña Marta y la farmacéutica Lucía). 2.5D: Vol (luz y sombra), 3 capas con parallax, giro leve, sombra en el suelo.
export const SUBS={arriba:1330,size:84,acento:'#FFC83D'};
type C=[string,string,string];
const SH=.2; // cada imagen entra 0,2 s (6 cuadros) antes de su palabra
const A=[0,9,26,44,67,81,104,129,143].map(T);
const SB=[0,...A.slice(1).map(a=>a-SH),DUR];
const q=(s:number,a:number,b:number,e:(x:number)=>number=Easing.inOut(Easing.cubic))=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:e});
const pop=(s:number,t0:number,d=.4)=>q(s,t0,t0+d,Easing.out(Easing.back(2)));
const mix=(a:number,b:number,u:number)=>a+(b-a)*u;
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}Q${x+w} ${y} ${x+w} ${y+r}V${y+h-r}Q${x+w} ${y+h} ${x+w-r} ${y+h}H${x+r}Q${x} ${y+h} ${x} ${y+h-r}V${y+r}Q${x} ${y} ${x+r} ${y}Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const PUR:C=['#b99aff','#7B3CFF','#3a0f9a'],GOLD:C=['#fff2b8','#FFC83D','#a8700a'],WHI:C=['#ffffff','#f0f4f7','#a9b7c2'],GRN:C=['#9affc8','#22D37A','#0a7a40'],RED:C=['#ffa3a3','#FF4D4D','#9a1010'],MINT:C=['#c8fff0','#3DE0B5','#0b7a62'],
 CART:C=['#f4dcae','#c99b5a','#7a5428'],FUC:C=['#ff8cc4','#E8338B','#8a0f4a'],BLU:C=['#c4e6ff','#3aa0ff','#0a4a9a'],BAG:C=['#c99266','#7a4a28','#3c2010'],SIL:C=['#ffffff','#d6dde3','#8a98a6'],
 SKM:C=['#ffeadf','#f4bfa8','#b3705b'],SKL:C=['#b57554','#7a4630','#3b1a0e'],SKD:C=['#f2c79b','#cf9061','#7a4a2c'],MONEY:C=['#dcffd2','#6fd36a','#2c8a38'];
const Vol:React.FC<{d:string;c:C;sw?:number;o?:number;borde?:string;ob?:number}>=({d,c,sw=70,o=24,borde,ob=.55})=>{const id='v'+React.useId().replace(/:/g,'');return <g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={ob}/>
</g>;};
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.55'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='atom' cx='.35' cy='.3'><stop stopColor='#d8f2ff'/><stop offset='.5' stopColor='#2aa4ff'/><stop offset='1' stopColor='#0a3a9a'/></radialGradient>
 <radialGradient id='perla' cx='.35' cy='.3'><stop stopColor='#ffffff'/><stop offset='.7' stopColor='#ecebf2'/><stop offset='1' stopColor='#a9a8bd'/></radialGradient>
 <radialGradient id='pelob' cx='.4' cy='.3'><stop stopColor='#ffffff'/><stop offset='.7' stopColor='#e4e4ee'/><stop offset='1' stopColor='#9a9ab2'/></radialGradient>
 <linearGradient id='mfront' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#7ff5d6'/><stop offset='1' stopColor='#0c7d68'/></linearGradient>
 <linearGradient id='topdark' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#02140f' stopOpacity='.62'/><stop offset='1' stopColor='#02140f' stopOpacity='0'/></linearGradient>
 <linearGradient id='oro' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fff6c0'/><stop offset='.5' stopColor='#FFC83D'/><stop offset='1' stopColor='#b8780a'/></linearGradient>
 <radialGradient id='vin' cx='.5' cy='.5' r='.75'><stop offset='.62' stopColor='#000' stopOpacity='0'/><stop offset='1' stopColor='#000' stopOpacity='.5'/></radialGradient>
</defs>;
const Txt:React.FC<{x:number;y:number;t:string;size:number;fill?:string;sh?:string;rot?:number;ls?:number}>=({x,y,t,size,fill='#fff',sh='#000',rot=0,ls=0})=><g transform={`rotate(${rot} ${x} ${y})`}>
 <text x={x+4} y={y+6} textAnchor='middle' fontSize={size} fontWeight={900} fill={sh} opacity='.45' letterSpacing={ls}>{t}</text>
 <text x={x} y={y} textAnchor='middle' fontSize={size} fontWeight={900} fill={fill} letterSpacing={ls}>{t}</text></g>;

// ---------- tiempos atados a la voz ----------
const W={marca:en('marca'),caja:en('caja'),farm:en('Farmacia'),pres:en('presión'),caja2:en('caja',2),bonita:en('bonita'),farmac:en('farmacéutica'),ensena:en('enseña'),blanca:en('blanca'),gen:en('genérico'),ella:en('Ella'),no:en('no'),mas:en('más'),debil:en('débil'),
 esto:en('esto'),estados:en('Estados'),mismo:en('mismo'),ingr:en('ingrediente'),activo:en('activo'),dosis:en('dosis'),igual:en('igual'),
 revisa:en('revisa'),fda:en('FDA'),fda2:en('FDA',2),misma2:en('misma',2),agencia:en('agencia'),aprueba:en('aprueba'),marca2:en('marca',2),
 precio:en('precio'),cuesta:en('cuesta'),och1:en('ochenta'),och2:en('ochenta',2),menos:en('menos'),
 cien:en('cien'),mes:en('mes'),gen4:en('genérico',4),podria:en('podría'),quince:en('quince'),veinte:en('veinte'),extra:en('extra'),paga:en('paga'),nombre:en('nombre'),
 antes:en('Antes'),pregunta:en('pregunta'),gen5:en('genérico',5),medico:en('médico'),acuerdo:en('acuerdo'),
 tu:en('tu',2),like:en('like'),envia:en('envíaselo'),medic:en('medicinas'),cada:en('cada'),mes2:en('mes',2)};

// ---------- mano con volumen: palma, dedos con nudillos y uñas, anillo, manga ----------
const FING:[number,number,number][]=[[-45,92,28],[-15,112,30],[15,102,29],[45,80,26]];
const Mano:React.FC<{x:number;y:number;k?:number;rot?:number;pose?:'plana'|'abierta'|'senala'|'pulgar';c:C;anillo?:boolean;mang?:C;flip?:boolean;largo?:number}>=({x,y,k=1,rot=0,pose='plana',c,anillo=false,mang=WHI,flip=false,largo=300})=>{
 const nail='#ffe9e0';
 const tips=(fx:number,ty:number,w:number,show:boolean)=>show?<ellipse cx={fx} cy={ty+11} rx={w*.33} ry={w*.4} fill={nail} stroke={c[2]} strokeWidth={2} opacity={.95}/>:null;
 let body:React.ReactNode;
 if(pose==='pulgar'){
  body=<>
   <Vol d={caps(0,40,0,170,100)} c={c} sw={40} o={12}/>
   <Vol d={caps(0,150,0,largo,116)} c={mang} sw={50} o={14}/>
   <Vol d={rr(-62,140,124,26,10)} c={mang} sw={20} o={6} borde={mang[2]}/>
   <Vol d={rr(-66,-96,132,150,38)} c={c} sw={50} o={14}/>
   {[-72,-44,-16,12].map((yy,j)=><g key={j}><Vol d={caps(-52,yy+8,28,yy+8,28)} c={c} sw={14} o={4}/></g>)}
   <Vol d={caps(-34,-70,-34,-168,46)} c={c} sw={26} o={8}/>
   <ellipse cx={-34} cy={-170} rx={15} ry={19} fill={nail} stroke={c[2]} strokeWidth={2}/>
   <path d='M-46 -104Q-34 -96 -20 -104' stroke={c[2]} strokeWidth={3} fill='none' opacity='.5'/>
   <Brillo2 x={-52} y={-130} rx={9} ry={30} r={10} o={.5}/>
  </>;
 } else {
  const sen=pose==='senala',pal=pose==='abierta';
  body=<>
   <Vol d={caps(0,40,0,170,104)} c={c} sw={40} o={12}/>
   <Vol d={caps(0,150,0,largo,120)} c={mang} sw={50} o={14}/>
   <Vol d={rr(-64,140,128,26,10)} c={mang} sw={20} o={6} borde={mang[2]}/>
   {FING.map(([fx,len,w],j)=>{const L=sen&&j>0?42:len;return <g key={j}>
    <Vol d={caps(fx,-108,fx,-108-L,w)} c={c} sw={18} o={5}/>
    {[.4,.72].map((u,m)=>L>60?<path key={m} d={`M${fx-w*.28} ${-108-L*u}h${w*.56}`} stroke={c[2]} strokeWidth={2.5} opacity={.45}/>:null)}
    {tips(fx,-108-L-(j>0&&sen?0:0),w,!pal)}
    {anillo&&j===2&&!sen&&<g><ellipse cx={fx} cy={-108-L*.3} rx={w*.55} ry={7} fill='none' stroke={GOLD[2]} strokeWidth={9}/><ellipse cx={fx} cy={-108-L*.3-1} rx={w*.55} ry={7} fill='none' stroke={GOLD[0]} strokeWidth={4}/><circle cx={fx} cy={-108-L*.3-8} r={6} fill='#8ff0ff' stroke='#fff' strokeWidth={1.5}/></g>}
   </g>})}
   <Vol d='M-64 0C-76 -46 -76 -86 -66 -116C-30 -128 30 -128 66 -116C76 -86 76 -46 64 0Z' c={c} sw={50} o={14}/>
   {!pal&&FING.map(([fx],j)=><ellipse key={j} cx={fx} cy={-106} rx={13} ry={7} fill={c[0]} opacity={.55}/>)}
   {pal&&<><path d='M-40 -70Q0 -30 44 -52' stroke={c[2]} strokeWidth={3.5} fill='none' opacity={.5}/><path d='M-52 -40Q-10 -8 30 -20' stroke={c[2]} strokeWidth={3} fill='none' opacity={.4}/></>}
   <Vol d={caps(-60,-24,sen?-70:-112,sen?-62:-92,36)} c={c} sw={20} o={6}/>
   {!pal&&<ellipse cx={sen?-70:-112} cy={sen?-62:-92} rx={12} ry={14} fill={nail} stroke={c[2]} strokeWidth={2} opacity={.9}/>}
   <Brillo2 x={-34} y={-70} rx={10} ry={34} r={8} o={.4}/>
  </>;
 }
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${flip?-k:k} ${k})`}>{body}</g>;
};

// ---------- cajas: marca (morada) y genérico (blanca) ----------
const Estrella:React.FC<{x:number;y:number;r:number;o?:number}>=({x,y,r,o=1})=><path d={`M${x} ${y-r}Q${x} ${y} ${x+r} ${y}Q${x} ${y} ${x} ${y+r}Q${x} ${y} ${x-r} ${y}Q${x} ${y} ${x} ${y-r}Z`} fill='#fff7c8' opacity={o}/>;
const HEART='M0 34C-84 -18 -50 -78 0 -34C50 -78 84 -18 0 34Z';
const Caja:React.FC<{x:number;y:number;k?:number;rot?:number;tipo:'marca'|'gen';glow?:number;brillo?:number;sombra?:boolean}>=({x,y,k=1,rot=0,tipo,glow=0,brillo=-1,sombra=true})=>{
 const w=260,h=340,d=96,a=rot*Math.PI/180,cs=Math.cos(a),sn=Math.sin(a),back=cs<0,ac=Math.max(.04,Math.abs(cs)),as=Math.abs(sn),fw=w*ac,sw=d*as,ds=sw*.3,right=sn>=0,tot=fw+sw,fx=right?-tot/2:-tot/2+sw;
 const idc='cj'+React.useId().replace(/:/g,'');
 const sideC:C=tipo==='marca'?['#9a72ff','#5a28d0','#2a0c70']:['#eef3f6','#c9d3da','#7e8c98'],topC:C=tipo==='marca'?['#d8c4ff','#a47eff','#5a30c0']:['#ffffff','#f4f8fa','#bcc8d2'];
 const sideP=right?`M${fx+fw} ${-h}L${fx+fw+sw} ${-h-ds}L${fx+fw+sw} ${-ds}L${fx+fw} 0Z`:`M${fx} ${-h}L${fx-sw} ${-h-ds}L${fx-sw} ${-ds}L${fx} 0Z`;
 const topP=right?`M${fx} ${-h}L${fx+fw} ${-h}L${fx+fw+sw} ${-h-ds}L${fx+sw} ${-h-ds}Z`:`M${fx} ${-h}L${fx+fw} ${-h}L${fx+fw-sw} ${-h-ds}L${fx-sw} ${-h-ds}Z`;
 const front=!back?(tipo==='marca'?<>
   <Vol d={rr(0,0,w,h,12)} c={PUR} sw={110} o={34}/>
   <Vol d={rr(0,h*.09,w,24,0)} c={GOLD} sw={16} o={4}/><Vol d={rr(0,h*.87,w,24,0)} c={GOLD} sw={16} o={4}/>
   <g transform={`translate(${w/2} ${h*.4}) scale(1.35)`}><Vol d={HEART} c={GOLD} sw={34} o={9}/><path d='M-52 -22Q-44 -52 -16 -40' stroke='#fff' strokeWidth={7} fill='none' opacity='.8' strokeLinecap='round'/></g>
   <Txt x={w/2} y={h*.74} t='MARCA' size={48} fill={GOLD[1]} sh='#2a0c70'/>
   <Estrella x={34} y={h*.26} r={14}/><Estrella x={w-38} y={h*.58} r={10}/><Estrella x={46} y={h*.62} r={8}/>
  </>:<>
   <Vol d={rr(0,0,w,h,12)} c={WHI} sw={90} o={26}/>
   <g transform={`translate(${w/2} ${h*.2}) rotate(-35)`}><Vol d={caps(-42,0,42,0,40)} c={GRN} sw={14} o={4}/><path d='M0 -20V20' stroke='#fff' strokeWidth={4} opacity='.8'/><Brillo2 x={-22} y={-8} rx={14} ry={5} r={0} o={.7}/></g>
   <Vol d={rr(0,h*.38,w,h*.27,0)} c={GRN} sw={40} o={10}/>
   {glow>0&&<text x={w/2} y={h*.38+h*.27/2+14} textAnchor='middle' fontSize={36} fontWeight={900} fill='#ffffaa' filter='url(#b18)' opacity={glow}>GENÉRICO</text>}
   <Txt x={w/2} y={h*.38+h*.27/2+13} t='GENÉRICO' size={35} fill={glow>0?interpolateColors(glow,[0,1],['#ffffff','#fffbb0']):'#fff'} sh='#064a28'/>
   {[0,1,2].map(j=><rect key={j} x={34} y={h*.74+j*18} width={w-68-(j===2?60:0)} height={7} rx={3.5} fill='#cfd8de'/>)}
  </>):(tipo==='marca'?<>
   <Vol d={rr(0,0,w,h,12)} c={PUR} sw={110} o={34}/>
   {[0,1,2,3,4,5].map(j=><Txt key={j} x={w/2+(j%2?34:-34)} y={46+j*58} t='MARCA' size={44} fill={GOLD[1]} sh='#2a0c70' rot={-14}/>)}
  </>:<><Vol d={rr(0,0,w,h,12)} c={WHI} sw={90} o={26}/><Vol d={rr(0,h*.4,w,h*.2,0)} c={GRN} sw={30} o={8}/></>);
 return <g transform={`translate(${x} ${y}) scale(${k})`}>
  {sombra&&<ellipse cy={6} rx={tot*.62+30} ry={30} fill='#000' opacity='.38' filter='url(#b18)'/>}
  <Vol d={sideP} c={sideC} sw={40} o={10}/>
  <Vol d={topP} c={topC} sw={30} o={8}/>
  <g transform={`translate(${fx} ${-h}) scale(${ac} 1)`}>{front}
   {brillo>=0&&<><defs><clipPath id={idc}><path d={rr(0,0,w,h,12)}/></clipPath></defs><g clipPath={`url(#${idc})`}><path d={`M${-120+brillo*(w+260)} ${h}L${-60+brillo*(w+260)} ${h}L${60+brillo*(w+260)} 0L${0+brillo*(w+260)} 0Z`} fill='#fff' opacity='.5' filter='url(#b6)'/></g></>}
  </g>
 </g>;
};
const Blister:React.FC<{x:number;y:number;k?:number;rot?:number}>=({x,y,k=1,rot=0})=><g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
 <Vol d={rr(-70,-22,140,44,8)} c={SIL} sw={20} o={6}/>
 {[0,1,2,3,4].map(j=><g key={j}><ellipse cx={-48+j*24} cy={4} rx={9} ry={9} fill='#000' opacity='.25'/><circle cx={-48+j*24} cy={0} r={9} fill='url(#pelob)' stroke='#8a98a6' strokeWidth={1.5}/></g>)}</g>;
// Caja que se abre: casi todo cartón y papel, solo una tira pequeña de pastillas.
const CajaAbierta:React.FC<{x:number;y:number;k?:number;p:number;tira?:boolean;rot?:number}>=({x,y,k=1,p,tira=true,rot=0})=>{
 const lid=Math.min(1,p)*240;
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
  <ellipse cy={12} rx={250} ry={38} fill='#000' opacity='.38' filter='url(#b18)'/>
  <Vol d={`M-100 -410L100 -410L${128+lid*.1} ${-410-lid}L${-128-lid*.1} ${-410-lid}Z`} c={['#d8c4ff','#9a6aff','#4a1ec0']} sw={60} o={18}/>
  <Vol d={`M-84 ${-410-lid*.22}L84 ${-410-lid*.22}L84 ${-410-lid*.3}L-84 ${-410-lid*.3}Z`} c={GOLD} sw={10} o={3}/>
  <Vol d='M-140 -300L140 -300L104 -410L-104 -410Z' c={CART} sw={50} o={14}/>
  <Vol d='M-120 -306L120 -306L90 -398L-90 -398Z' c={WHI} sw={26} o={8}/>
  <Vol d='M-100 -312L110 -318L84 -386L-70 -392Z' c={['#ffffff','#f4f6f9','#bcc6d0']} sw={20} o={6} ob={.3}/>
  {[0,1,2,3,4,5].map(j=><rect key={j} x={-76+j*4} y={-372+j*10} width={150-j*12} height={4} rx={2} fill='#aab4c0' opacity='.7'/>)}
  <path d='M-110 -306L-70 -392M60 -306L84 -390' stroke='#c2cad4' strokeWidth={3}/>
  {tira&&<Blister x={-50} y={-324} k={.7} rot={-7}/>}
  <Vol d={rr(-150,-300,300,300,10)} c={PUR} sw={110} o={34}/>
  <Vol d={rr(-150,-266,300,22,0)} c={GOLD} sw={14} o={4}/><Vol d={rr(-150,-52,300,22,0)} c={GOLD} sw={14} o={4}/>
  <g transform='translate(0 -160) scale(.95)'><Vol d={HEART} c={GOLD} sw={34} o={9}/></g>
  <Txt x={0} y={-76} t='MARCA' size={40} fill={GOLD[1]} sh='#2a0c70'/>
 </g>;
};

// ---------- personas ----------
const Persona:React.FC<{kind:'marta'|'lucia'|'medico';x:number;y:number;k?:number;s:number;rot?:number;abre?:number;sonrisa?:number;cejas?:number;mira?:number;lentes?:number;fase?:number}>=({kind,x,y,k=1,s,rot=0,abre=0,sonrisa=.3,cejas=0,mira=0,lentes=0,fase=0})=>{
 const id=React.useId().replace(/:/g,'');
 const sk=kind==='marta'?SKM:kind==='lucia'?SKL:SKD,iris=kind==='marta'?'#5f87ad':kind==='lucia'?'#3a2216':'#4a3020';
 const bl=Math.max(0,1-Math.abs(((s+fase)%3.6)-3.4)*12),eb=Math.max(.1,1-bl*.9);
 const wc=kind==='marta'?20:kind==='lucia'?20:20;
 const mw=54-abre*8,yc=140-sonrisa*14,yu=128-sonrisa*6-abre*2,yl=yc+8+abre*58+sonrisa*30;
 const mouth=`M${-mw} ${yc}Q0 ${yu} ${mw} ${yc}Q0 ${yl} ${-mw} ${yc}Z`;
 const hairC:C=kind==='marta'?['#ffffff','#e8e8f0','#a4a4bc']:kind==='lucia'?['#6a4a40','#2a1a14','#0a0402']:['#6a4a3a','#2a1810','#0a0402'];
 return <g transform={`translate(${x} ${y}) rotate(${rot} 0 200) scale(${k})`}>
  {/* torso */}
  <Vol d='M-62 140L-80 300L0 440L80 300L62 140Z' c={sk} sw={40} o={12}/>
  {kind==='marta'&&<Vol d='M-330 720C-330 440 -240 340 -90 300L0 440L90 300C240 340 330 440 330 720Z' c={FUC} sw={120} o={36}/>}
