// macro: la mano con anillo desliza una caja sobre el mostrador (cuadro 0 y cierre en bucle)
const Macro:React.FC<{s:number;t0:number;tipo:'marca'|'gen'}>=({s,t0,tipo})=>{
 const u=Math.max(0,s-t0),e=Easing.out(Easing.cubic)(Math.min(1,u/1.6)),k=1.5,rot=mix(36,-14,e),a=rot*Math.PI/180;
