 return <g>
  <rect x={-300} y={1240} width={1680} height={900} fill='url(#mfront)'/>
  <Vol d={rr(-300,1240,1680,900,0)} c={['#ffffff','#e4fff6','#7acbb8']} sw={120} o={40}/>
