  <ellipse cx={600} cy={1262} rx={420} ry={20} fill='#fff' opacity='.7' filter='url(#b6)'/>
  <Caja x={bx} y={1262} k={k} rot={rot} tipo={tipo} brillo={((u*.7)%1.6)-.3}/>
  <Mano x={tip+400} y={1090} k={1.7} rot={-90} pose='plana' c={SKL} anillo mang={WHI} largo={420}/>
 </g>;
};

